INSERT INTO users(role_id,name,email,password_hash) VALUES ((SELECT id FROM roles WHERE name='Super Admin'),'System Administrator','admin@college.com','$2y$12$.4se4pVDOdfbqT5DoppvEuVAKrBxbqONZ8JVrZlSgSM5a.c/tvhEq'),((SELECT id FROM roles WHERE name='Faculty'),'Demo Faculty','faculty@college.com','$2y$12$asoD8SWgr.XiwoNvc1aYG.cDgLJ/4ivPXW0.qwbVUvYr8I.5LDwRe'),((SELECT id FROM roles WHERE name='Student'),'Demo Student','student@college.com','$2y$12$EB8p0CAs8jH0GyKigzI8n.dUmp0vdlfUhvqimXdU13jvsrbLQhXky'),((SELECT id FROM roles WHERE name='Parent/Guardian'),'Demo Parent','parent@college.com','$2y$12$hxcfr3MDllaAMtylHbQD1eOfQmJrhIkeHD8KeEJY1fGFXjSZJmw4W');
INSERT INTO faculty(user_id,employee_id,department_id,designation,qualification) SELECT u.id,'FAC001',d.id,'Assistant Professor','M.Tech' FROM users u JOIN departments d ON d.code='CE' WHERE u.email='faculty@college.com';
INSERT INTO students(user_id,enrollment_no,admission_no,department_id,branch_id,course_id,academic_year_id,semester_id,division_id,admission_date) SELECT u.id,'CE2026001','ADM001',d.id,b.id,c.id,ay.id,s.id,v.id,CURDATE() FROM users u JOIN departments d ON d.code='CE' JOIN branches b ON b.code='CO' JOIN courses c ON c.code='DIP' JOIN academic_years ay ON ay.is_current=1 JOIN semesters s ON s.number=5 JOIN divisions v ON v.name='A' WHERE u.email='student@college.com';
INSERT INTO parents(user_id,relationship,mobile) SELECT id,'Parent','+91 9999999999' FROM users WHERE email='parent@college.com';
INSERT INTO parent_students(parent_id,student_id) SELECT p.id,s.id FROM parents p JOIN users u ON u.id=p.user_id CROSS JOIN students s WHERE u.email='parent@college.com' AND s.enrollment_no='CE2026001';
INSERT INTO subjects(branch_id,semester_id,code,name,credits,subject_type,max_marks,passing_marks) SELECT b.id,s.id,'CE-501','Database Management Systems',4,'Theory',100,40 FROM branches b JOIN semesters s ON s.number=5 WHERE b.code='CO';
INSERT INTO subjects(branch_id,semester_id,code,name,credits,subject_type,max_marks,passing_marks) SELECT b.id,s.id,'CE-502','Web Technology',4,'Theory',100,40 FROM branches b JOIN semesters s ON s.number=5 WHERE b.code='CO';
INSERT INTO subjects(branch_id,semester_id,code,name,credits,subject_type,max_marks,passing_marks) SELECT b.id,s.id,'CE-503','Advanced Programming',4,'Practical',100,40 FROM branches b JOIN semesters s ON s.number=5 WHERE b.code='CO';
INSERT INTO faculty_subjects(faculty_id,subject_id) SELECT f.id,s.id FROM faculty f JOIN subjects s ON s.code IN ('CE-501','CE-502','CE-503') WHERE f.employee_id='FAC001';
INSERT INTO student_subjects(student_id,subject_id) SELECT st.id,s.id FROM students st JOIN subjects s ON s.code IN ('CE-501','CE-502','CE-503') WHERE st.enrollment_no='CE2026001';
INSERT INTO books(isbn,title,author,publisher,category,year) VALUES ('978000001','Digital Systems','A. Author','Nova Press','Engineering',2076),('978000002','Advanced PHP','P. Developer','Tech Press','Programming',2077);
INSERT INTO book_copies(book_id,accession_no) SELECT id,CONCAT('ACC-',id,'-01') FROM books;
