INSERT INTO student_fees(student_id,fee_structure_id,category,amount,discount,paid_amount,due_date,status) SELECT s.id,f.id,'Tuition Fee',45000,5000,15000,DATE_ADD(CURDATE(),INTERVAL 30 DAY),'Pending' FROM students s JOIN fee_structures f ON f.name='Diploma Semester 5' LIMIT 1;
INSERT INTO applications(applicant_user_id,application_type,title,status,owner_role,current_stage) SELECT id,'service','Welcome Digital Campus','Submitted','Student','Published' FROM users WHERE email='student@college.com';
INSERT INTO certificates(student_id,type,certificate_no,issue_date,status,issuer_user_id) SELECT s.id,'Bonafide Certificate','CERT-2077-DEMO',CURDATE(),'Issued',u.id FROM students s JOIN users u ON u.email='admin@college.com' WHERE s.enrollment_no='CE2026001';
INSERT INTO certificate_verifications(certificate_id,verification_code) SELECT id,'VERIFY-CERT-2077-DEMO' FROM certificates WHERE certificate_no='CERT-2077-DEMO';
