USE college_management;
CREATE TABLE activity_logs(id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id INT NULL,role_name VARCHAR(80),action VARCHAR(80),module VARCHAR(80),record_id INT NULL,description TEXT,ip_address VARCHAR(64),user_agent VARCHAR(500),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX idx_activity(created_at,module),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE password_resets(id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id INT,token_hash VARCHAR(255),expires_at DATETIME,used_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE login_attempts(id BIGINT AUTO_INCREMENT PRIMARY KEY,email VARCHAR(190),ip_address VARCHAR(64),attempted_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,success TINYINT DEFAULT 0,INDEX idx_login(email,ip_address,attempted_at));
CREATE TABLE alumni(id BIGINT AUTO_INCREMENT PRIMARY KEY,student_id INT UNIQUE NOT NULL,graduation_year YEAR,status VARCHAR(30) DEFAULT 'Active',current_company VARCHAR(180),designation VARCHAR(150),contact_email VARCHAR(190),contact_mobile VARCHAR(30),profile_url VARCHAR(255),notes TEXT,FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE);
